    const d = new Date(); d.setHours(0, 0, 0, 0); d.setDate(d.getDate() - i); const t = d.getTime();
    daily.push({ date: t, revenue: o.filter((r) => r.created_at >= t && r.created_at < t + 864e5).reduce((a, r) => a + r.total, 0) });
